<?php
declare(strict_types=1);require __DIR__.'/common.php';
$connections=parse_xml_connections();$tx=active_and_history($connections);$online=online_index($connections);$modules=[];foreach(cfg()['modules'] as $letter=>$meta){$mc=array_values(array_filter($connections,fn($c)=>$c['module']===$letter));$protocols=array_values(array_unique(array_filter(array_column($mc,'protocol'))));$last=null;foreach($tx['history'] as $h){if($h['module']===$letter){$last=$h;break;}}$modules[$letter]=['module'=>$letter,'name'=>$meta['name'],'configured_protocol'=>$meta['protocol'],'access'=>$meta['access'],'connected_count'=>count($mc),'protocols'=>$protocols,'transmission'=>$tx['active'][$letter]??null,'last_transmission'=>$last];}
$history=array_map(function($h) use ($online){$h['online']=!empty($online[$h['callsign']]);return $h;}, $tx['history']);
json_out(['ok'=>true,'generated_at'=>time(),'server_name'=>cfg()['server_name'],'active_count'=>count($tx['active']),'connected_count'=>count($connections),'modules'=>$modules,'history'=>$history,'connections'=>$connections,'sources'=>['xml'=>is_readable(cfg()['xml_path']),'log'=>is_readable(cfg()['log_path']),'db'=>is_readable(cfg()['users_db'])]]);
